from __future__ import annotations
from typing import Dict, List, Sequence, Tuple

def divisors(n: int) -> List[int]:
    """All positive divisors of n, sorted ascending. O(sqrt n)."""
    ds: List[int] = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            ds.append(i)
            if i != n // i:
                ds.append(n // i)
        i += 1
    return sorted(ds)


def euler_phi(n: int) -> int:
    """Euler's totient, by trial division. O(sqrt n)."""
    result, m, p = n, n, 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1
    if m > 1:
        result -= result // m
    return result


def divisor_spectrum(a: int, b: int) -> List[int]:
    """
    The divisor spectrum S(a,b) = { d : d | ab, d does not divide a, d does not divide b }.

    The Alexander polynomial of the torus knot T(a,b) is the cyclotomic product
    Delta_{a,b} = prod_{d in S(a,b)} Phi_d, so this list *is* the irreducible
    factorization of the invariant, in index form.
    """
    return [d for d in divisors(a * b) if a % d != 0 and b % d != 0]


def spectrum_report(a: int, b: int) -> Dict[str, object]:
    """Spectrum, factor degrees, total degree and factor count for T(a,b)."""
    spec = divisor_spectrum(a, b)
    degs = [euler_phi(d) for d in spec]
    return {
        "spectrum": spec,
        "factor_degrees": degs,
        "degree": sum(degs),                       # equals (a-1)(b-1)
        "num_factors": len(spec),                  # equals (tau(a)-1)(tau(b)-1)
        "degree_check": sum(degs) == (a - 1) * (b - 1),
        "factor_count_check":
            len(spec) == (len(divisors(a)) - 1) * (len(divisors(b)) - 1),
    }
